if(inviteInfo){try{const response=await fetch('/api/worker/session');if(response.status===403){const data=await response.json();message.textContent=data.error||'근로자 접속이 차단되었습니다.';}else if(response.ok){const data=await response.json();if(data.worker.site_id===inviteInfo.id&&!workerOpening&&!document.querySelector('#worker-logout')){const restore=async location=>{const access=await fetch('/api/worker/access',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reportContext:data.reportContext,siteId:inviteInfo.id,siteKey,token,...(location?{location}:{})})}),result=await access.json();if(!access.ok)throw Error(result.error||'출역 기록을 확인하지 못했습니다.');adoptSiteAddress(result.siteKey);await showWorker(data.worker,data.reportContext);};if(inviteInfo.locationRequired){const button=document.createElement('button');button.type='button';button.id='worker-resume-location';button.textContent='위치 확인 후 기존 로그인으로 계속';message.after(button);button.onclick=async()=>{if(workerOpening)return;workerOpening=true;button.disabled=true;try{await restore(await captureWorkerLocation());}catch(error){message.textContent=error.message;button.disabled=false;}finally{workerOpening=false;}};}else{workerOpening=true;try{await restore();}finally{workerOpening=false;}}}}}catch(error){message.textContent=error.message||'시험 세션을 확인하지 못했습니다.';}}
